scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    chb_Grp_All.setValue(1);
    scwin.fn_allCheck();

    /*
    		//  기간 from~ to  셋팅
    		var vCurDate = cGetToday("yyyymmdd");
    		edt_SDate.text = '19000101';    // 백윤경대리 요청(2008.10.07)
    		//edt_SDate.text = cGetMinusDate2(vCurDate, 3650);  // 1년전 날짜
    		edt_SDate.text = cGetToday("yyyymmdd");     // 현재날짜
    		edt_EDate.text = cGetToday("yyyymmdd");     // 현재날짜
    */
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10);
    var str = "";
    for (var i = yyyy; i >= 2004; i--) {
        str += i + "^" + i + "년,";
    }
    str = str.substring(0, str.length - 1);
    //alert(str);
    cmb_STD_YEAR.CBData = str;

    //Combo_CBDataSetPeriod(cmb_PeriodTp);

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();

    /*
    		dts_Indp.DataID="/ListedSearch.do?method=listMiddleIndustry&outputMessageId=LIST_MIDDLE_INDUSTRY" ;
    		dts_Indp.Reset();
    */

};
scwin.fn_allCheck = function() {
    var checkArray = [chb_Grp_St, chb_Grp_Sc, chb_Grp_Rt, chb_Grp_Dr, chb_Grp_Fs];
    if (chb_Grp_All.checked == true) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
scwin.fn_list_sync = function() {
    var secuGrpId = "";
    if ($c.stf.getObjectValue(chb_Grp_St) == 'Y') secuGrpId += 'ST,';
    //if (getObjectValue(chb_Grp_Mf) == 'Y')        secuGrpId += 'MF,';
    if ($c.stf.getObjectValue(chb_Grp_Rt) == 'Y') secuGrpId += 'RT,';
    if ($c.stf.getObjectValue(chb_Grp_Sc) == 'Y') secuGrpId += 'SC,';
    if ($c.stf.getObjectValue(chb_Grp_Fs) == 'Y') secuGrpId += 'FS,';
    if ($c.stf.getObjectValue(chb_Grp_Dr) == 'Y') secuGrpId += 'DR,';
    //if (getObjectValue(chb_Grp_If) == 'Y')    secuGrpId += 'IF,';
    if ($c.stf.getObjectValue(chb_Grp_All) == ' Y') secuGrpId = '';
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LIST_EMP_CNT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.empcnt" + "&{P}param01=" + $c.stf.getObjectValue(rdo_LIST_STAT_CD) + // 상장구분
        "&{P}param02=" + $c.stf.getObjectValue(rdo_LIST_STAT_CD) + // 상장구분
        "&{P}param03=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 법인코드회사코드
        "&{P}param04=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 법인코드회사코드
        "&{P}param05=" + $c.stf.getObjectValue(cmb_TeamList) + // 담당팀
        "&{P}param06=" + $c.stf.getObjectValue(cmb_TeamList) + // 담당팀
        "&{P}param07=" + $c.stf.getObjectValue(cmb_EmpList) + // 담당자
        "&{P}param08=" + $c.stf.getObjectValue(cmb_EmpList) + // 담당자
        "&{P}param09=" + $c.stf.getObjectValue(rdo_MARKET_TP_CD) + // 시장구분
        "&{P}param10=" + $c.stf.getObjectValue(rdo_MARKET_TP_CD) + // 시장구분
        "&{P}param11=" + secuGrpId + // 회사구분
        "&{P}param12=" + secuGrpId + // 회사구분
        "&{P}param13=" + $c.stf.getObjectValue(cmb_STD_YEAR) + // 시작일자
        "&{P}param14=" + $c.stf.getObjectValue(cmb_STD_YEAR); // 시작일자

    /*

    		 "&{P}param13=" + getObjectValue(edt_SDate) + // 시작일자
    		 "&{P}param14=" + getObjectValue(edt_SDate); // 시작일자

    		var url = "/listingCommon.do?method=listGeneral" +
    			"&outputMessageId=LIST_CORPORATIONBOOK_ISUINST" +
    			"&service=krx.lds.stf.listingcommon.services.ListingCommonApp" +
    			"&queryId=lds.stf.lstsrch.select.isuinst.condition"+
    			"&{P}param01=" + getObjectValue(rdo_MARKET_TP_CD) + // 시장구분
    			"&{P}param02=" + getObjectValue(rdo_MARKET_TP_CD) + // 시장구분
    			"&{P}param03=" + secuGrpId + // 회사구분
    			"&{P}param04=" + secuGrpId + // 회사구분
    			"&{P}param05=" + getObjectValue(rdo_LIST_STAT_CD) + // 상장구분
    			"&{P}param06=" + getObjectValue(rdo_LIST_STAT_CD) + // 상장구분
    			"&{P}param07=" + getObjectValue(txb_ISUR_CD) + // 법인코드
    			"&{P}param08=" + getObjectValue(txb_ISUR_CD) + // 법인코드
    			"&{P}param09=" + getObjectValue(rdo_LIST_DATE_COND) +// 기간 조건
    			"&{P}param10=" + getObjectValue(edt_SDate) +// 시작일자
    			"&{P}param11=" + getObjectValue(edt_EDate) +// 종료일자
    			"&{P}param12=" + getObjectValue(rdo_LIST_DATE_COND) +// 기간 조건
    			"&{P}param13=" + getObjectValue(edt_SDate) +// 시작일자
    			"&{P}param14=" + getObjectValue(edt_EDate) +// 종료일자
    			"&{P}param15=" + getObjectValue(cmb_TeamList) +// 팀
    			"&{P}param16=" + getObjectValue(cmb_TeamList) +// 팀
    			"&{P}param17=" + getObjectValue(cmb_EmpList) +// 사원
    			"&{P}param18=" + getObjectValue(cmb_EmpList) +// 사원
    			"&{P}param19=" + getObjectValue(cmb_INDP) +// 업종
    			"&{P}param20=" + getObjectValue(cmb_INDP) +// 업종
    			"&{P}param21=" + getObjectValue(cmb_ACNTCLS_MMDD1) +// 결산월
    			"&{P}param22=" + getObjectValue(cmb_ACNTCLS_MMDD1) +// 결산월
    			"&{P}param23=" + getObjectValue(rdo_ADMISU_YN) +// 관리종목여부
    			"&{P}param24=" + getObjectValue(rdo_ADMISU_YN);// 관리종목여부

    */

    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);

    /*
    var url = "/ListedSearch.do?method=listCorporationBook&inputMessageId=LIST_CORPORATIONBOOK_ISUINST" ;
    url +="&gubun=1" ;
    url +="&LIST_STAT_CD=" +   cmd_List.BindColVal;
    url +="&COM_ATTR_TP_CD=" + secuGrpId ; //cmb_InstLIst.BindColVal;
    url +="&SPOT_ISU_TRD_MKT_TP_CD="  +  rdo_TrdGubun.codeValue ;
    url +="&STD_IND_CD=" + cmb_Industry.BindColVal;
    url +="&ISUR_CD=" +getObjectValue(txb_IsurCd);
    url +="&ADMISU_YN=" ;//+cmb_AdminYn.BindColVal;
    url +="&HALT_YN=" ;  // +cmb_HoltYn.BindColVal;
    url +="&TRANSSTK_AGNT_CD=" ;//+cmb_TransCd.BindColVal;
    url +="&ACNTCLS_MMDD=" ;//+cmb_Acntcls.BindColVal;
    url +="&DEP_CD=" + cmb_depList.BindColVal;
    url +="&EMP_NO=" +cmb_EmpList.BindColVal;
    //url +="&YYYYMMDD1=" +getObjectValue(edt_SDate);
    //url +="&YYYYMMDD2=" +getObjectValue(edt_EDate);
    */

};
scwin.fn_setContnId = function(obj) {
    scwin.gIsurCd = dts_List.getCellData(eval(obj), "ISUR_CD");
};
scwin.img_COM_NM_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.btn_Search_onclick = function() {
    //if ( compareFromToDate2(edt_SDate, edt_EDate) ) {
    scwin.fn_list_sync();
    //}

};
scwin.chb_Grp_Sc_onclick = function() {
    chb_Grp_All.setValue(0);
};
scwin.chb_Grp_Rt_onclick = function() {
    chb_Grp_All.setValue(0);
};
scwin.chb_Grp_Dr_onclick = function() {
    chb_Grp_All.setValue(0);
};
scwin.chb_Grp_Fs_onclick = function() {
    chb_Grp_All.setValue(0);
};
scwin.chb_Grp_St_onclick = function() {
    chb_Grp_All.setValue(0);
};
scwin.chb_Grp_All_onclick = function() {
    scwin.fn_allCheck();
};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_TeamList, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd || dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.grd_List_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 엑셀	
    $c.data.downloadGridViewExcel(grd_List, "상장원부현황", "", "8");
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page_1);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.gform_onload = function() {
    //fn_search_year();

    if (js_market == "1" || js_market == "2" || js_market == "6") {
        $c.cm.setColumnProp(grd_List, "TR_MKT_NM", "Show", false);
        $c.stf.setObjectValue(rdo_MARKET_TP_CD, js_market);
        $c.stf.showObj(panel_mkt_gubun, false);
    } else {
        $c.stf.showObj(panel_mkt_gubun, true);
    }
    if (js_market == "2") {
        $c.cm.setColumnProp(grd_List, "INPROSPCTS_EXST_STRT_DD", "Show", false);
        $c.cm.setColumnProp(grd_List, "ISUR_SYMBL", "Show", false);
    }
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_SetCode();

    //fn_list_sync();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
};
